function ScoreForm({
	ranking,
	onUpdateRanking,
	team1,
	team2,
	onSelectTeam1,
	onSelectTeam2,
	team1Score,
	team2Score,
	onAddP1Score,
	onAddP2Score,
	onAddScore,
}) {
	// Handle submit form
	function handleSubmit(e) {
		e.preventDefault();

		// Build the new result, and add it into the scoreBoard state/table.
		const newResult = {
			id: Date.now(),
			homeTeam: team1,
			awayTeam: team2,
			result: team1Score + " : " + team2Score,
		};
		if (team1 && team2) {
			onAddScore(newResult);
		} else {
			alert("Select both teams, please.");
		}
		if (newResult) {
			if (team1Score > team2Score) {
				console.log("Player1 scored more goals");
				console.log(team1);
				const team1NewResults = {
					points: team1.points + 3,
					win: team1.wins + 1,
					draws: team1.draws,
					losses: team1.losses,
					goalsFor: team1.goalsFor + team1Score,
					goalsAgainst: team1.goalsAgainst + team2Score,
					goalDifference: team1.goalDifference + (team1Score - team2Score),
				};
				onUpdateRanking();
			} else if (team2Score > team1Score) {
				console.log("Player2 scored more goals!");
			} else {
				console.log("Tie! No winner today.");
			}
		} else {
			console.log("Nothing to update!");
		}
	}

	const playerObj = ranking.map((player) => player);
	const {
		id,
		teamName,
		points,
		wins,
		draws,
		losses,
		goalsFor,
		goalsAgainst,
		goalDifference,
	} = playerObj;

	return (
		<div className="scores">
			<form onSubmit={handleSubmit}>
				<span>
					<select
						defaultValue={"home"}
						value={teamName}
						onChange={(e) => onSelectTeam1(e.target.value)}
						required
					>
						<option value="home" disabled>
							Home Team
						</option>
						<option value={playerObj[0].teamName}>
							{playerObj[0].teamName}
						</option>
						<option value={playerObj[1].teamName}>
							{playerObj[1].teamName}
						</option>
						<option value={playerObj[2].teamName}>
							{playerObj[2].teamName}
						</option>
					</select>
					<input
						type="number"
						value={team1Score}
						onChange={(e) => onAddP1Score(e.target.value)}
						required
					/>
				</span>
				:
				<span>
					<select
						defaultValue={"away"}
						value={teamName}
						onChange={(e) => onSelectTeam2(e.target.value)}
						required
					>
						<option value="away" disabled>
							Away Team
						</option>
						<option value={playerObj[0].teamName}>
							{playerObj[0].teamName}
						</option>
						<option value={playerObj[1].teamName}>
							{playerObj[1].teamName}
						</option>
						<option value={playerObj[2].teamName}>
							{playerObj[2].teamName}
						</option>
					</select>
					<input
						type="number"
						value={team2Score}
						onChange={(e) => onAddP2Score(e.target.value)}
						required
					/>
				</span>
				<button>Add</button>
			</form>
		</div>
	);
}
export default ScoreForm;
